// Retrieve a font file by its token.
async function getFont(fontToken: string) {
  try {
    const fontData = await client.getFont({ fontToken });
    console.log("Font data:", fontData);
    return fontData;
  } catch (error) {
    console.error("Error retrieving font:", error);
    return null;
  }
}
```

